"use strict";(self.webpackChunkeleven_plus_core_concepts=self.webpackChunkeleven_plus_core_concepts||[]).push([[5958],{5958:e=>{e.exports=JSON.parse('{"concept":"3D Cube Block Reasoning","subject":"mathematics","category":"3D Shapes & Spatial Analysis","explanation":"These problems involve visualizing cubes made of unit blocks. Key skills: counting visible vs hidden blocks, understanding that corner blocks touch 3 faces, edge blocks touch 2 faces, face-center blocks touch 1 face. A 3\xd73\xd73 cube has 27 blocks total, but some are completely hidden inside.","examples":[{"question":"A 3\xd73\xd73 cube is made of unit cubes. How many unit cubes can you see from the outside?","solution":"26 unit cubes","explanation":"Total cubes = 3\xb3 = 27. The center cube is completely hidden. All other 26 cubes touch at least one face and are visible from outside."},{"question":"A large cube is made of 64 small cubes arranged in a 4\xd74\xd74 pattern. How many small cubes are completely hidden inside?","solution":"8 small cubes","explanation":"Hidden cubes form a 2\xd72\xd72 inner cube (removing one layer from each face). So 2\xb3 = 8 cubes are completely hidden."},{"question":"In a 3\xd73\xd73 cube, how many unit cubes have exactly 2 faces showing?","solution":"12 unit cubes","explanation":"These are the edge cubes (not corners, not face centers). Each edge of the cube has 1 such cube, and a cube has 12 edges, so 12 cubes show exactly 2 faces."}],"exercises":[{"type":"multiple-choice","question":"A 2\xd72\xd72 cube is painted red on all faces, then broken into unit cubes. How many unit cubes have exactly 3 red faces?","options":["0","4","6","8"],"correct":[3],"explanation":"In a 2\xd72\xd72 cube, all 8 unit cubes are corner cubes, and each corner touches exactly 3 faces. So all 8 cubes have 3 red faces."},{"type":"multiple-choice","question":"In a 4\xd74\xd74 cube made of unit cubes, how many unit cubes touch exactly one face of the large cube?","options":["24","36","48","54"],"correct":[0],"explanation":"Face-center cubes touch exactly 1 face. Each face is 4\xd74, so has (4-2)\xd7(4-2) = 4 interior cubes. With 6 faces: 6\xd74 = 24 cubes."},{"type":"open-ended","question":"A 5\xd75\xd75 cube is built from unit cubes. Explain how to find the number of unit cubes that are completely inside (touching no faces).","sample_answer":"Remove one layer from each direction to find the inner cube. 5\xd75\xd75 becomes 3\xd73\xd73 inside. So 3\xb3 = 27 cubes are completely hidden.","explanation":"Interior cubes form a smaller cube that\'s 2 units smaller in each dimension."}],"tips":["Corner cubes touch 3 faces, edge cubes touch 2, face-center cubes touch 1","Hidden cubes form a smaller inner cube","For n\xd7n\xd7n cube: hidden cubes = (n-2)\xb3 if n > 2","Visualize layer by layer: corners, edges, faces, interior","Draw diagrams to help visualize the problem"]}')}}]);